        tkey.key_header[9]  = akd;
        tkey.key_header[10] = 0x03;
        tkey.key_header[11] = 0xa0;
        tkey.key     = NULL;
        tkey.key_len = 0;

        return sc_card_ctl(card, SC_CARDCTL_STARCOS_WRITE_KEY, &tkey);
}

