static int
sc_transmit(sc_card_t *card, sc_apdu_t *apdu)
{
        struct sc_context *ctx  = card->ctx;
        size_t       olen  = apdu->resplen;
        int          r;

        LOG_FUNC_CALLED(ctx);

        r = sc_single_transmit(card, apdu);
