```

sc_transmit is called. Looking at sc_transmit:

```c
static int
sc_transmit(sc_card_t *card, sc_apdu_t *apdu)
{
    ...
    r = sc_single_transmit(card, apdu);
    LOG_TEST_RET(ctx, r, "transmit APDU failed");

    /* 0x6Cxx handling */
    if (apdu->sw1 == 0x6C && ...)

    /* 0x61xx handling */
    if (apdu->sw1 == 0x61 && ...)

